(()=>{const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('.nav');if(menu&&nav){menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>nav.classList.remove('open')))}const progress=document.getElementById('progress'),topBtn=document.querySelector('.back-top');const update=()=>{const max=document.documentElement.scrollHeight-innerHeight; if(progress)progress.style.width=(max>0?scrollY/max*100:0)+'%';if(topBtn)topBtn.classList.toggle('show',scrollY>500)};addEventListener('scroll',update,{passive:true});update();if(topBtn)topBtn.addEventListener('click',()=>scrollTo({top:0,behavior:'smooth'}));const els=document.querySelectorAll('.reveal');if('IntersectionObserver'in window){const io=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');io.unobserve(e.target)}}),{threshold:.12});els.forEach(el=>io.observe(el))}else els.forEach(el=>el.classList.add('visible'))})();